'use client';

import React, { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Upload, ImageIcon } from 'lucide-react';
import { UploadSchema } from '@/lib/zod';
import { BookUploadFormValues } from '@/types';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { ACCEPTED_PDF_TYPES, ACCEPTED_IMAGE_TYPES, DEFAULT_VOICE } from '@/lib/constants';
import FileUploader from './FileUploader';
import VoiceSelector from './VoiceSelector';
import LoadingOverlay from './LoadingOverlay';

import {useAuth, useUser} from "@clerk/nextjs";
import { toast } from 'sonner';
import {checkBookExists, createBook, saveBookSegments} from "@/lib/actions/book.actions";
import {useRouter} from "next/navigation";
import {parsePDFFile} from "@/lib/utils";
import {upload} from "@vercel/blob/client";

const UploadForm = () => {
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isMounted, setIsMounted] = useState(false);

    const { userId } = useAuth();
    const router = useRouter()

    useEffect(() => {
        setIsMounted(true);
    }, []);

    const form = useForm<BookUploadFormValues>({
        resolver: zodResolver(UploadSchema),
        defaultValues: {
            title: '',
            author: '',
            persona: '',
            pdfFile: undefined,
            coverImage: undefined,
        },
    });

    const onSubmit = async (data: BookUploadFormValues) => {
        if(!userId) {
            return toast.error("Please login to upload books");
        }

        setIsSubmitting(true);



        try {
            const existsCheck = await checkBookExists(data.title);

            if(existsCheck.exists && existsCheck.book) {
                toast.info("Book with same title already exists.");
                form.reset()
                router.push(`/books/${existsCheck.book.slug}`)
                return;
            }

            const fileTitle = data.title.replace(/\s+/g, '-').toLowerCase();
            const pdfFile = data.pdfFile;

            const parsedPDF = await parsePDFFile(pdfFile);

            if(parsedPDF.content.length === 0) {
                toast.error("Failed to parse PDF. Please try again with a different file.");
                return;
            }

            const uploadedPdfBlob = await upload(fileTitle, pdfFile, {
                access: 'public',
                handleUploadUrl: '/api/upload',
                contentType: 'application/pdf'
            });

            let coverUrl: string;

            if(data.coverImage) {
                const coverFile = data.coverImage;
                const uploadedCoverBlob = await upload(`${fileTitle}_cover.png`, coverFile, {
                    access: 'public',
                    handleUploadUrl: '/api/upload',
                    contentType: coverFile.type
                });
                coverUrl = uploadedCoverBlob.url;
            } else {
                const response = await fetch(parsedPDF.cover)
                const blob = await response.blob();

                const uploadedCoverBlob = await upload(`${fileTitle}_cover.png`, blob, {
                    access: 'public',
                    handleUploadUrl: '/api/upload',
                    contentType: 'image/png'
                });
                coverUrl = uploadedCoverBlob.url;
            }

            const book = await createBook({
                clerkId: userId,
                title: data.title,
                author: data.author,
                persona: data.persona,
                fileURL: uploadedPdfBlob.url,
                fileBlobKey: uploadedPdfBlob.pathname,
                coverURL: coverUrl,
                fileSize: pdfFile.size,
            });

            if(!book.success) {
                const errorMsg = book.error as string || "Failed to create book";
                toast.error(errorMsg);
                setIsSubmitting(false);
                return;
            }

            if(book.alreadyExists) {
                toast.info("Book with same title already exists.");
                form.reset()
                router.push(`/books/${book.data.slug}`)
                return;
            }

            const segments = await saveBookSegments(book.data._id, userId, parsedPDF.content);

            if(!segments.success) {
                toast.error("Failed to save book segments");
                throw new Error("Failed to save book segments");
            }

            form.reset();
            router.push('/');
        // } catch (error) {
        //     console.error(error);
        //
        //     toast.error("Failed to upload book. Please try again later.");
        } catch (error) {
            const message = error instanceof Error
                ? error.message
                : typeof error === 'string'
                    ? error
                    : JSON.stringify(error);

            console.error('Upload submission error:', message);
            toast.error(message || "Failed to upload book. Please try again later.");

        } finally {
            setIsSubmitting(false);
        }
    };

    if (!isMounted) return null;

    return (
        <>
            {isSubmitting && <LoadingOverlay />}

            <div className="new-book-wrapper">
                <Form {...form}>

                    {/*==========================================================*/}
                     <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-8">


                        {/* 1. PDF File Upload */}
                        <FileUploader
                            control={form.control}
                            name="pdfFile"
                            label="Book PDF File"
                            acceptTypes={ACCEPTED_PDF_TYPES}
                            icon={Upload}
                            placeholder="Click to upload PDF"
                            hint="PDF file (max 50MB)"
                            disabled={isSubmitting}
                        />

                        {/* 2. Cover Image Upload */}
                        <FileUploader
                            control={form.control}
                            name="coverImage"
                            label="Cover Image (Optional)"
                            acceptTypes={ACCEPTED_IMAGE_TYPES}
                            icon={ImageIcon}
                            placeholder="Click to upload cover image"
                            hint="Leave empty to auto-generate from PDF"
                            disabled={isSubmitting}
                        />

                        {/* 3. Title Input */}
                        <FormField
                            control={form.control}
                            name="title"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="form-label">Title</FormLabel>
                                    <FormControl>
                                        <Input
                                            className="form-input"
                                            placeholder="ex: Rich Dad Poor Dad"
                                            {...field}
                                            disabled={isSubmitting}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        {/* 4. Author Input */}
                        <FormField
                            control={form.control}
                            name="author"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="form-label">Author Name</FormLabel>
                                    <FormControl>
                                        <Input
                                            className="form-input"
                                            placeholder="ex: Robert Kiyosaki"
                                            {...field}
                                            disabled={isSubmitting}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        {/* 5. Voice Selector */}
                        <FormField
                            control={form.control}
                            name="persona"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="form-label">Choose Assistant Voice</FormLabel>
                                    <FormControl>
                                        <VoiceSelector
                                            value={field.value}
                                            onChange={field.onChange}
                                            disabled={isSubmitting}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        {/* 6. Submit Button */}
                        <Button type="submit" className="form-btn" disabled={isSubmitting}>
                            Begin Synthesis
                        </Button>

                     </form>
                </Form>
            </div>
        </>
    );
};

export default UploadForm;

'use client';

import { useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { auth } from '@clerk/nextjs/server';
import Image from 'next/image';
import { ArrowLeft, Mic, MicOff } from 'lucide-react';
import { getBookBySlug } from '@/lib/actions/book.actions';

export default function BookDetailsPage({ params }: { params: { slug: string } }) {
  const router = useRouter();
  const [book, setBook] = useEffect<any>(null);
  const [loading, setLoading] = useEffect(true);
  const [error, setError] = useEffect<string | null>(null);

  useEffect(() => {
    const fetchBook = async () => {
      try {
        // Check authentication
        const { userId } = await auth();
        if (!userId) {
          router.push('/');
          return;
        }

        // Fetch book by slug
        const result = await getBookBySlug(params.slug);

        if (!result.success || !result.data) {
          setError('Book not found');
          setTimeout(() => router.push('/'), 2000);
          return;
        }

        setBook(result.data);
      } catch (err) {
        console.error('Error fetching book:', err);
        setError('Failed to load book');
      } finally {
        setLoading(false);
      }
    };

    fetchBook();
  }, [params.slug, router]);

  if (loading) {
    return (
      <div className="book-page-container flex items-center justify-center">
        <div className="text-center">
          <div className="inline-block animate-spin">
            <Mic className="w-12 h-12 text-[#663820]" />
          </div>
          <p className="mt-4 text-lg font-medium text-[var(--text-primary)]">Loading book...</p>
        </div>
      </div>
    );
  }

  if (error || !book) {
    return (
      <div className="book-page-container flex items-center justify-center">
        <div className="text-center">
          <p className="text-lg font-medium text-red-600">{error || 'Book not found'}</p>
          <p className="text-sm text-[var(--text-muted)] mt-2">Redirecting...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="book-page-container">
      {/* Back Button */}
      <button
        onClick={() => router.push('/')}
        className="back-btn-floating hover:bg-gray-50"
        aria-label="Go back"
      >
        <ArrowLeft className="w-5 h-5 text-[var(--text-primary)]" />
      </button>

      {/* Main Container - Centered with max-w-4xl */}
      <div className="mx-auto max-w-4xl flex flex-col gap-6">
        {/* Header Card */}
        <div className="vapi-header-card">
          {/* Book Cover with Mic Button */}
          <div className="vapi-cover-wrapper">
            <Image
              src={book.coverURL || '/assets/book-cover.svg'}
              alt={book.title}
              width={120}
              height={180}
              className="vapi-cover-image"
              priority
            />
            {/* Floating Mic Button */}
            <div className="vapi-mic-wrapper">
              <button
                className="vapi-mic-btn"
                aria-label="Start voice conversation"
                title="Start voice conversation"
              >
                <MicOff className="w-6 h-6 text-[#212a3b]" />
              </button>
            </div>
          </div>

          {/* Book Info Section */}
          <div className="flex flex-col flex-1 min-w-0">
            {/* Title and Author */}
            <h1 className="font-serif text-2xl sm:text-3xl font-bold text-[#212a3b] mb-1">
              {book.title}
            </h1>
            <p className="text-[#3d485e] text-base sm:text-lg mb-4">
              by {book.author}
            </p>

            {/* Badge Row */}
            <div className="flex flex-wrap gap-2 sm:gap-3">
              {/* Status Badge */}
              <div className="vapi-status-indicator">
                <span className="vapi-status-dot vapi-status-dot-ready"></span>
                <span className="vapi-status-text">Ready</span>
              </div>

              {/* Voice Badge */}
              <div className="vapi-status-indicator">
                <span className="vapi-status-text">Voice: {book.persona || 'Default'}</span>
              </div>

              {/* Timer Badge */}
              <div className="vapi-status-indicator">
                <span className="vapi-status-text">0:00/15:00</span>
              </div>
            </div>
          </div>
        </div>

        {/* Transcript Area */}
        <div className="transcript-container min-h-[400px]">
          <div className="transcript-empty">
            <Mic className="w-12 h-12 text-[#212a3b] mb-4" />
            <p className="transcript-empty-text">No conversation yet</p>
            <p className="transcript-empty-hint">Click the mic button above to start talking</p>
          </div>
        </div>
      </div>
    </div>
  );
}

